//! #627: `module.exports = function g() {}` and `exports.f = function g() {}` (named function
//! expressions, `g != f` allowed) are CommonJS callable facts. The variant matrix lives in
//! `tests/fixtures/js_cjs_named_fn_expr/matrix.jsonl` (generated by the script recorded in the PR):
//! the producer (`m.js` unless `producer_file` says otherwise), the consumer (`app.js`), the callee
//! spelling and the outcome of that callee's call sites in the consumer. `admit` rows must resolve to
//! the one Exact `import_member` edge named (they fail on base 105599ee); `refuse` rows pin the
//! unresolved outcome and must carry no Exact `import_member`; `control` rows already hold on main.
use super::js_relative_extension_test::graph;
use prism::call_graph::CallGraph;
use serde::Deserialize;

#[derive(Deserialize)]
pub(super) struct Row {
    pub(super) id: String,
    pub(super) kind: String,
    pub(super) producer: String,
    pub(super) consumer: String,
    pub(super) callee: String,
    pub(super) expect: Vec<String>,
    pub(super) consumer_file: Option<String>,
    pub(super) producer_file: Option<String>,
    pub(super) extra: Option<Vec<(String, String)>>,
}

const MATRIX: &str = include_str!("../fixtures/js_cjs_named_fn_expr/matrix.jsonl");

pub(super) fn outcome(cg: &CallGraph, callee: &str, file: &str) -> Vec<String> {
    let mut out = Vec::new();
    for site in cg
        .calls
        .values()
        .flatten()
        .filter(|s| s.callee_name == callee && s.caller.file == file)
    {
        let res = cg.resolve_call_site_full(site);
        match res.drop {
            Some(drop) => out.push(format!("drop {drop:?}")),
            None => out.extend(res.resolved.iter().map(|r| {
                format!(
                    "{}:{}@{}-{} {:?}/{}",
                    r.target.file,
                    r.target.name,
                    r.target.start_line,
                    r.target.end_line,
                    r.confidence,
                    r.kind.as_str()
                )
            })),
        }
    }
    out.sort();
    out
}

fn rows() -> Vec<Row> {
    MATRIX
        .lines()
        .map(|l| serde_json::from_str(l).expect("matrix row"))
        .collect()
}

#[test]
fn variant_matrix_holds() {
    let mut failures = Vec::new();
    let all = rows();
    assert!(all.len() >= 100, "matrix shrank to {} rows", all.len());
    for row in &all {
        let file = row.consumer_file.as_deref().unwrap_or("app.js");
        let producer = row.producer_file.as_deref().unwrap_or("m.js");
        let mut files: Vec<(&str, &str)> = vec![
            (producer, row.producer.as_str()),
            (file, row.consumer.as_str()),
        ];
        for (path, src) in row.extra.iter().flatten() {
            files.push((path.as_str(), src.as_str()));
        }
        let cg = graph(&files);
        let actual = outcome(&cg, &row.callee, file);
        if actual != row.expect {
            failures.push(format!(
                "{} [{}]: expected {:?}, got {:?}",
                row.id, row.kind, row.expect, actual
            ));
        }
        let exact_import = actual.iter().any(|a| a.contains("Exact/import_member"));
        let shape_ok = match row.kind.as_str() {
            "admit" => exact_import && actual.len() == 1,
            "refuse" => !exact_import,
            "control" => true,
            other => panic!("row {}: unknown kind {other}", row.id),
        };
        if !shape_ok {
            failures.push(format!(
                "{}: kind {} contradicts {:?}",
                row.id, row.kind, actual
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} rows:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

/// Every producer shape and consumer shape the brief names is present, so a row cannot be dropped silently.
#[test]
fn matrix_covers_the_named_shapes() {
    let all = rows();
    for needle in [
        "mv-named/named-fn",
        "mv-named/arrow",
        "mv-named/module-level",
        "mv-named/decl-same-name-before",
        "mv-named/decl-same-name-after",
        "mv-named/reassigned-after",
        "mv-named/member-mutation-after",
        "mv-named/async",
        "mv-named/generator",
        "mv-named/esm-export",
        "mv-named/parse-error",
        "mv-named/anonymous",
        "member-exports-dot/named-fn-member",
        "member-module-exports-dot/named-fn-member",
        "member-exports-dot/destructured",
        "member-exports-dot/recursive",
        "member-object-pair/named-fn-member",
        "member-exports-dot/two-same-name-exprs",
    ] {
        assert!(all.iter().any(|r| r.id.starts_with(needle)), "{needle}");
    }
    assert!(all.iter().filter(|r| r.kind == "admit").count() >= 50);
    assert!(all.iter().filter(|r| r.kind == "refuse").count() >= 40);
}
